.bfusion-license-badge{position:absolute;left:6px;bottom:6px;font:11px/1.3 "Segoe UI",system-ui,sans-serif;padding:3px 8px;border-radius:3px;z-index:10;pointer-events:none;background:transparent;color:#9AA0A6;}
.bfusion-license-badge--trial{background:transparent;color:#9AA0A6;box-shadow:none;border:none;}
.bfusion-license-badge--licensed{background:transparent;color:#9AA0A6;box-shadow:none;border:none;}
.bfusion-license-badge em{opacity:.85;font-style:normal;}
.bfusion-trial-watermark{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:5;}
